package cl.bolsillo.app;

import org.json.*;
import java.text.Normalizer;
import java.util.*;

/** Read-only views over transactions: historical records and balances stay untouched. */
final class ConceptCatalog {
 static String normalize(String raw){String n=Normalizer.normalize(raw==null?"":raw,Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").trim();return n.replaceAll(" +"," ");}
 static String concept(String raw){ServiceCatalog.Entry service=ServiceCatalog.identify(raw);return service==null?normalize(raw):service.id;}
 static String label(String raw){ServiceCatalog.Entry service=ServiceCatalog.identify(raw);return service==null?(raw==null?"":raw.trim()):service.name;}
 static boolean generic(String normalized){return normalized.isEmpty()||Arrays.asList("gasto","ingreso","compra detectada","ingreso detectado","compra","transferencia","transferencia recibida","abono recibido","gasto dictado","ingreso dictado").contains(normalized);}
 static String key(JSONObject t){String type=t.optString("type"),raw=t.optString("note");String k=concept(raw);if(!type.equals("expense")&&!type.equals("income")||generic(k))return type+"#"+t.optString("id");return type+":"+k;}
 static final class Group {final String key,type;String label,lastDate,category;long total;final List<JSONObject> items=new ArrayList<>();Group(String key,JSONObject t){this.key=key;type=t.optString("type");label=label(t.optString("note"));lastDate=t.optString("date");category=t.optString("category");}int count(){return items.size();}}
 static List<Group> groups(JSONArray transactions)throws Exception{LinkedHashMap<String,Group> map=new LinkedHashMap<>();for(int i=0;i<transactions.length();i++){JSONObject t=transactions.getJSONObject(i);String k=key(t);Group g=map.get(k);if(g==null){g=new Group(k,t);map.put(k,g);}g.items.add(t);g.total=Math.addExact(g.total,t.optLong("amount"));if(t.optString("date").compareTo(g.lastDate)>0){g.lastDate=t.optString("date");g.label=label(t.optString("note"));g.category=t.optString("category");}}List<Group> groups=new ArrayList<>(map.values());for(Group g:groups)g.items.sort((a,b)->b.optString("date").compareTo(a.optString("date")));groups.sort((a,b)->{int c=b.lastDate.compareTo(a.lastDate);return c!=0?c:a.label.compareToIgnoreCase(b.label);});return groups;}
 static List<String> suggestions(JSONObject data,String type)throws Exception{LinkedHashMap<String,String> names=new LinkedHashMap<>();JSONArray tx=data.getJSONArray("transactions");for(int i=tx.length()-1;i>=0;i--){JSONObject t=tx.getJSONObject(i);if(!t.optString("type").equals(type))continue;String raw=t.optString("note").trim(),k=concept(raw);if(raw.length()>1&&!generic(k)&&!names.containsKey(k))names.put(k,label(raw));}JSONArray recurring=data.optJSONArray("recurring");if(recurring!=null)for(int i=recurring.length()-1;i>=0;i--){JSONObject r=recurring.getJSONObject(i);if(!r.optString("type").equals(type))continue;String raw=r.optString("name").trim(),k=concept(raw);if(raw.length()>1&&!generic(k)&&!names.containsKey(k))names.put(k,label(raw));}return new ArrayList<>(names.values());}
 static String preferredCategory(JSONObject data,String type,String note)throws Exception{String wanted=concept(note);if(wanted.isEmpty())return "";JSONArray tx=data.getJSONArray("transactions");Map<String,Integer> score=new HashMap<>();for(int i=0;i<tx.length();i++){JSONObject t=tx.getJSONObject(i);if(t.optString("type").equals(type)&&concept(t.optString("note")).equals(wanted)){String category=t.optString("category");if(!category.isEmpty())score.put(category,score.getOrDefault(category,0)+1);}}JSONArray recurring=data.optJSONArray("recurring");if(recurring!=null)for(int i=0;i<recurring.length();i++){JSONObject r=recurring.getJSONObject(i);if(r.optString("type").equals(type)&&concept(r.optString("name")).equals(wanted)){String category=r.optString("category");if(!category.isEmpty())score.put(category,score.getOrDefault(category,0)+2);}}String best="";int count=0;for(Map.Entry<String,Integer> entry:score.entrySet())if(entry.getValue()>count){best=entry.getKey();count=entry.getValue();}return best;}
 static JSONObject ensureCategory(JSONObject data,String type,String name)throws Exception{String clean=name.trim(),wanted=normalize(clean);Ledger.require(clean.length()>=2&&clean.length()<=50,"La categoría debe tener entre 2 y 50 caracteres");JSONArray cats=data.getJSONArray("categories");for(int i=0;i<cats.length();i++){JSONObject c=cats.getJSONObject(i);if(c.optString("type").equals(type)&&normalize(c.optString("name")).equals(wanted)){c.put("archived",false);return c;}}JSONObject c=new JSONObject().put("id",Ledger.id()).put("name",clean).put("type",type).put("emoji","").put("color","#087F79").put("archived",false);cats.put(c);return c;}
}
